package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public final class ReferenceSourceTests {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static String read(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),assets=Paths.get(args[1]).getParent();for(String language:new String[]{"python","java"}){Path out=root.resolve(language+"-android");Files.createDirectories(out);String runtime=read(assets.resolve(language.equals("python")?"PythonRuntime.py":"JavaRuntime.txt"));for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String name=line.split("\\t")[0],ext=language.equals("python")?".py":".java";FlowModel.Document d=FlowCodec.decode(read(root.resolve("android-"+name+".frociart")));String before=FlowCodec.encode(d);FlowSource.Program ir=FlowSource.compile(d);check(ir.canGenerate(),name+" valid IR");FlowSourceText code=language.equals("python")?FlowPython.generate(ir,runtime):FlowJava.generate(ir,runtime,"Programma");check(code.text.equals((language.equals("python")?FlowPython.generate(ir,runtime):FlowJava.generate(ir,runtime,"Programma")).text),name+" deterministic");check(before.equals(FlowCodec.encode(d)),name+" original unchanged");check(code.text.equals(read(root.resolve(language+"-pc").resolve(name+ext))),name+" identical PC/Android code");for(FlowSource.Scope scope:ir.scopes)for(FlowSource.Block block:scope.blocks)check(!code.forBlock(scope.id,block.id).isEmpty(),name+" source mapping");Files.write(out.resolve(name+ext),code.text.getBytes(StandardCharsets.UTF_8));System.out.println("PASS "+language+" "+name);}}System.out.println("REFERENCE_SOURCE_ANDROID PASS checks="+checks);}
}
